"""Generate a bitsliced, constant-time AES S-box for vani and verify it
exhaustively in Python by simulating the exact generated operation list."""

def gmul(a, b):
    r = 0
    for _ in range(8):
        if b & 1: r ^= a
        hi = a & 0x80
        a = (a << 1) & 0xff
        if hi: a ^= 0x1b
        b >>= 1
    return r

def ginv(x):
    r = 1
    for _ in range(254): r = gmul(r, x)
    return r if x else 0

def sbox(x):
    i = ginv(x)
    s = i
    for k in range(1, 5): s ^= ((i << k) | (i >> (8 - k))) & 0xff
    return s ^ 0x63

REF = [sbox(x) for x in range(256)]

# Linear squaring matrix: square(x) bit j = XOR of x bits in SQ[j]
SQ = [[] for _ in range(8)]
for i in range(8):
    v = gmul(1 << i, 1 << i)
    for j in range(8):
        if (v >> j) & 1: SQ[j].append(i)

lines = []          # vani statements
counter = [0]
def tmp():
    counter[0] += 1
    return f"t{counter[0]}"

def emit(expr):
    t = tmp()
    lines.append(f"  let {t}: u32 = {expr};")
    return t

def xor_all(terms):
    if not terms: return "(0 as u32)"
    acc = terms[0]
    for t in terms[1:]:
        acc = emit(f"{acc} ^ {t}")
    return acc

def bs_square(a):
    return [xor_all([a[i] for i in SQ[j]]) for j in range(8)]

def bs_mul(a, b):
    # schoolbook product -> 15 coefficients, then reduce by x^8 = x^4+x^3+x+1
    prod = [[] for _ in range(15)]
    for i in range(8):
        for j in range(8):
            prod[i + j].append(emit(f"{a[i]} & {b[j]}"))
    c = [xor_all(p) for p in prod]
    for k in range(14, 7, -1):
        for d in (4, 3, 1, 0):
            c[k - 8 + d] = emit(f"{c[k - 8 + d]} ^ {c[k]}")
    return c[:8]

x = [f"p{i}" for i in range(8)]
x2 = bs_square(x)
x3 = bs_mul(x2, x)
x6 = bs_square(x3)
x12 = bs_square(x6)
x15 = bs_mul(x12, x3)
x30 = bs_square(x15)
x60 = bs_square(x30)
x120 = bs_square(x60)
x240 = bs_square(x120)
x252 = bs_mul(x240, x12)
x254 = bs_mul(x252, x2)
# affine: s_b = i_b ^ i_{b+4} ^ i_{b+5} ^ i_{b+6} ^ i_{b+7} ^ c_b ; c = 0x63, lanes all-ones mask for const bits
out = []
for b in range(8):
    t = xor_all([x254[b], x254[(b + 4) % 8], x254[(b + 5) % 8], x254[(b + 6) % 8], x254[(b + 7) % 8]])
    if (0x63 >> b) & 1:
        t = emit(f"{t} ^ (0xFFFF as u32)")   # 16 lanes used
    out.append(t)

# --- Python simulation of the emitted program over all 256 inputs in 16-lane batches
def run(planes):
    env = {f"p{i}": planes[i] for i in range(8)}
    for ln in lines:
        name, expr = ln.split("let ")[1].split(": u32 = ")
        expr = expr.rstrip(";").replace("(0xFFFF as u32)", "0xFFFF").replace("(0 as u32)", "0")
        env[name] = eval(expr, {}, env) & 0xFFFFFFFF
    return [env[o] if not o.startswith("(") else 0 for o in out]

ok = True
for base in range(0, 256, 16):
    vals = list(range(base, base + 16))
    planes = [sum(((v >> b) & 1) << lane for lane, v in enumerate(vals)) for b in range(8)]
    res = run(planes)
    for lane, v in enumerate(vals):
        s = sum(((res[b] >> lane) & 1) << b for b in range(8))
        if s != REF[v]:
            ok = False
            print("MISMATCH", v, hex(s), hex(REF[v]))
print("exhaustive check:", "PASS" if ok else "FAIL", "ops:", len(lines))

vani = ["// GENERATED by gen_bs_sbox.py (exhaustively verified against the",
        "// gf256_inv-based aes_sbox for all 256 inputs). Do not hand-edit.",
        "fn aes_sbox_bitsliced16(p0: u32, p1: u32, p2: u32, p3: u32, p4: u32, p5: u32, p6: u32, p7: u32) -> AesBsPlanes {"]
vani += lines
vani.append("  return AesBsPlanes { b0: %s, b1: %s, b2: %s, b3: %s, b4: %s, b5: %s, b6: %s, b7: %s };" % tuple(out))
vani.append("}")
open(__file__.replace("gen_bs_sbox.py", "bs_sbox.vani"), "w").write("\n".join(vani) + "\n")

# ---- register-allocated variant: reuse a small pool of mutable slots ----
import re
names = [ln.split("let ")[1].split(":")[0] for ln in lines]
exprs = [ln.split(" = ", 1)[1].rstrip(";") for ln in lines]
last_use = {}
for idx, e in enumerate(exprs):
    for tok in re.findall(r"\b(t\d+|p\d)\b", e):
        last_use[tok] = idx
for o in out:
    last_use[o] = len(exprs)
free, alloc, nslots = [], {}, 0
body = []
for idx, (nm, e) in enumerate(zip(names, exprs)):
    e2 = re.sub(r"\b(t\d+)\b", lambda m: alloc[m.group(1)], e)
    # free operands whose last use is this statement (before allocating dest)
    for tok in set(re.findall(r"\b(t\d+)\b", e)):
        if last_use.get(tok) == idx:
            free.append(alloc[tok])
    if free:
        slot = free.pop()
    else:
        slot = f"r{nslots}"; nslots += 1
    alloc[nm] = slot
    body.append(f"  {slot} = {e2};")
outs = [alloc[o] for o in out]
v2 = ["// GENERATED by gen_bs_sbox.py (exhaustively verified against the",
      "// gf256_inv-based aes_sbox for all 256 inputs; register-allocated so",
      f"// the frame holds {nslots} u32 slots, not {len(lines)}). Do not hand-edit.",
      "fn aes_sbox_bitsliced16(p0: u32, p1: u32, p2: u32, p3: u32, p4: u32, p5: u32, p6: u32, p7: u32) -> AesBsPlanes {"]
v2 += [f"  let r{i}: u32 = 0 as u32;" for i in range(nslots)]
v2 += body
v2.append("  return AesBsPlanes { b0: %s, b1: %s, b2: %s, b3: %s, b4: %s, b5: %s, b6: %s, b7: %s };" % tuple(outs))
v2.append("}")
# verify the register-allocated program too
def run2(planes):
    env = {f"p{i}": planes[i] for i in range(8)}
    for i in range(nslots): env[f"r{i}"] = 0
    for ln in body:
        dst, e = ln.strip().rstrip(";").split(" = ", 1)
        env[dst] = eval(e.replace("(0xFFFF as u32)", "0xFFFF").replace("(0 as u32)", "0"), {}, env) & 0xFFFFFFFF
    return [env[o] for o in outs]
ok2 = True
for base in range(0, 256, 16):
    vals = list(range(base, base + 16))
    planes = [sum(((v >> b) & 1) << lane for lane, v in enumerate(vals)) for b in range(8)]
    res = run2(planes)
    for lane, v in enumerate(vals):
        if sum(((res[b] >> lane) & 1) << b for b in range(8)) != REF[v]: ok2 = False
print("register-allocated exhaustive check:", "PASS" if ok2 else "FAIL", "slots:", nslots)
open(__file__.replace("gen_bs_sbox.py", "bs_sbox_ra.vani"), "w").write("\n".join(v2) + "\n")
